import { ariaAttr, boolAttr, dataAttr } from "../../dom/attrs";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import type { Align, Side } from "../../positioner/compute-position";
import { parts } from "./popover.anatomy";
import {
  getAnchorId,
  getArrowId,
  getBackdropId,
  getCloseTriggerId,
  getContentId,
  getDescriptionId,
  getPositionerId,
  getTitleId,
  getTriggerId,
} from "./popover.dom";
import type { PopoverApi, PopoverSchema } from "./popover.types";

export function connect<T extends PropTypes>(
  service: Service<PopoverSchema>,
  normalize: NormalizeProps<T>,
): PopoverApi<T> {
  const { context, prop, computed, send, scope } = service;

  const open = context.get("open");
  const modal = prop("modal");
  const presentation = computed("presentation");
  const disabled = prop("disabled");
  const state = open ? "open" : "closed";
  const placement = context.get("currentPlacement");
  // Split here rather than imported: `compute-position` keeps its parser private,
  // and re-exporting one to save this line would widen the positioner's surface.
  const [side, align = "center"] = placement.split("-") as [Side, Align | undefined];

  const contentId = getContentId(scope);
  const titleId = getTitleId(scope);
  const descriptionId = getDescriptionId(scope);

  const hasTitle = context.get("hasTitle");
  const describedBy = [
    context.get("hasDescription") ? descriptionId : undefined,
    prop("describedBy"),
  ]
    .filter((id): id is string => id !== undefined && id !== "")
    .join(" ");

  const placementAttrs = { "data-side": side, "data-align": align };

  return {
    open,
    modal,
    presentation,
    placement,

    setOpen(next: boolean): void {
      send({ type: "OPEN.SET", open: next });
    },

    focusInitial(): void {
      send({ type: "CONTENT.FOCUS" });
    },

    getTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.trigger.attrs,
        id: getTriggerId(scope),
        type: "button",
        disabled,
        "aria-haspopup": "dialog",
        "aria-expanded": boolAttr(open),
        // Only while open — a dangling IDREF names nothing.
        "aria-controls": open ? contentId : undefined,
        "data-state": state,
        "data-disabled": dataAttr(disabled),
        onClick(event) {
          if (event.defaultPrevented || disabled) return;
          // A disclosure: the same button closes it. This is the one event where
          // the popover and the dialog genuinely differ.
          send({ type: "TRIGGER.CLICK" });
        },
        onKeyDown(event) {
          if (event.defaultPrevented || event.key !== "Tab" || event.shiftKey) return;
          // The machine guards this too. The condition is repeated here because
          // suppressing the browser's own Tab has to be decided synchronously,
          // and only the handler is in a position to do it: without the
          // `preventDefault`, focus would enter the surface and the native Tab
          // would immediately walk it out again.
          if (!open || prop("autoFocus")) return;
          event.preventDefault();
          send({ type: "TRIGGER.KEYDOWN", key: event.key, shiftKey: event.shiftKey });
        },
      }),

    // No ARIA and no state: it is a measuring box. It exists for the surfaces
    // that point at something other than the control that opened them.
    getAnchorProps: (): T["element"] =>
      normalize.element({ ...parts.anchor.attrs, id: getAnchorId(scope) }),

    getBackdropProps: (): T["element"] =>
      normalize.element({
        ...parts.backdrop.attrs,
        id: getBackdropId(scope),
        "aria-hidden": ariaAttr(true),
        "data-state": state,
        "data-presentation": presentation,
      }),

    /**
     * The floating element. **`data-side` and `data-align` are deliberately absent
     * here** — the position effect writes them onto this node directly, and an
     * adapter that also rendered them would fight the effect over the same two
     * attributes on every commit. They are published on `content` and `arrow`
     * instead, from `currentPlacement`, which is the same value one step later.
     */
    getPositionerProps: (): T["element"] =>
      normalize.element({
        ...parts.positioner.attrs,
        id: getPositionerId(scope),
        "data-sui-layer-parent": prop("parentId"),
        "data-state": state,
        "data-presentation": presentation,
      }),

    getContentProps: (): T["element"] =>
      normalize.element({
        ...parts.content.attrs,
        ...placementAttrs,
        id: contentId,
        role: "dialog",
        dir: context.get("surfaceDir") ?? prop("dir"),
        tabIndex: -1,
        "aria-modal": ariaAttr(modal),
        "aria-labelledby": hasTitle ? titleId : undefined,
        // Never both: one name, from the title when there is one.
        "aria-label": hasTitle ? undefined : prop("label"),
        "aria-describedby": describedBy === "" ? undefined : describedBy,
        "data-state": state,
        "data-modal": dataAttr(modal),
        "data-presentation": presentation,
        "data-nested": dataAttr(prop("parentId") !== undefined),
        // Posted even when the surface is not modal, unlike the dialog: a popover
        // is left with B, not by walking out of the bottom of it. tvOS convention.
        "data-snav": "container",
        "data-snav-trap": "",
      }),

    // Decoration, and it says so: the silhouette carries no meaning a reader
    // needs, and `--sui-arrow-x/y` lands on this node.
    getArrowProps: (): T["element"] =>
      normalize.element({
        ...parts.arrow.attrs,
        ...placementAttrs,
        id: getArrowId(scope),
        "aria-hidden": ariaAttr(true),
      }),

    getArrowTipProps: (): T["element"] => normalize.element({ ...parts.arrowTip.attrs }),

    getTitleProps: (): T["element"] => normalize.element({ ...parts.title.attrs, id: titleId }),

    getDescriptionProps: (): T["element"] =>
      normalize.element({ ...parts.description.attrs, id: descriptionId }),

    getCloseTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.closeTrigger.attrs,
        id: getCloseTriggerId(scope),
        type: "button",
        "data-state": state,
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "CLOSE.CLICK" });
        },
      }),
  };
}

import { query } from "../../dom/query";
import { getPartId } from "../../machine/ids";
import { getDocumentEl, type Scope } from "../../machine/scope";

const COMPONENT = "popover";

export function getTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "trigger");
}

export function getAnchorId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "anchor");
}

export function getBackdropId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "backdrop");
}

export function getPositionerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "positioner");
}

export function getContentId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "content");
}

export function getArrowId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "arrow");
}

export function getTitleId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "title");
}

export function getDescriptionId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "description");
}

export function getCloseTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "closeTrigger");
}

export function getTriggerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getTriggerId(scope));
}

/**
 * What the surface measures itself against. Falls back to the trigger, which is
 * the anchor in the overwhelming majority of cases — the separate part exists for
 * the ones where it is not, a menu button that opens over a whole toolbar being
 * the usual example.
 */
export function getAnchorEl(scope: Scope): HTMLElement | null {
  return scope.getById(getAnchorId(scope)) ?? getTriggerEl(scope);
}

/**
 * The anchor for the *direction* alone, which has one more fallback than the one
 * for geometry: `composed.tsx` calls a popover with neither trigger nor anchor a
 * real shape — a caret menu, a surface driven from a store — and resolving
 * against nothing answers `"ltr"` flat, the one direction an RTL page did not ask
 * for. Never folded into `getAnchorEl`: that one is also the element
 * `trackPosition` measures, and the document would anchor the surface to the
 * whole page.
 */
export function getDirAnchorEl(scope: Scope): HTMLElement | null {
  return getAnchorEl(scope) ?? getDocumentEl(scope);
}

export function getBackdropEl(scope: Scope): HTMLElement | null {
  return scope.getById(getBackdropId(scope));
}

/** The floating element: what gets the translate, never the content. */
export function getPositionerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getPositionerId(scope));
}

export function getContentEl(scope: Scope): HTMLElement | null {
  return scope.getById(getContentId(scope));
}

export function getArrowEl(scope: Scope): HTMLElement | null {
  return scope.getById(getArrowId(scope));
}

/** Same three fallbacks as the dialog, for the same reason: no document, no throw. */
export function getEnvironmentEl(scope: Scope): HTMLElement | null {
  return getContentEl(scope) ?? getTriggerEl(scope) ?? getDocumentEl(scope);
}

/**
 * Rooted on the **positioner**, unlike `dialog.dom.ts`, because the arrow is not
 * inside the content — a search from the surface would report `hasArrow: false`
 * for every popover that renders one. `observeChildren` is already `subtree: true`,
 * so watching the positioner sees the content's children too.
 */
export function hasPart(scope: Scope, part: string): boolean {
  return query(getPositionerEl(scope), `[data-part~="popover:${part}"]`) !== null;
}

/**
 * A popover is a non-modal dialog that anchors instead of centring.
 *
 * It reuses the dialog's two structural decisions verbatim — `context.open` is the
 * only source of truth and the state is a projection of it, and the order the
 * effects install in is a contract because the interpreter tears down in reverse —
 * and adds one of its own.
 *
 * **The position is installed before the focus, which is the reverse of nothing
 * the dialog had to decide.** Focus lands in the surface the moment the trap or
 * the entry action runs; if the surface is still sitting at `0,0` at that point,
 * the browser scrolls the page to `0,0` to reveal it. A dialog never had this
 * problem because a dialog has nothing to position.
 *
 * **The sheet is the same machine, one effect short.** `PRESENTATION.SYNC` targets
 * `open` with `reenter: true`, so a density flip while the surface is open tears
 * the whole open state down and builds it back: the position tracker leaves, the
 * scroll lock arrives, the geometry changes. Without the re-entry a sheet would
 * still be driven by `trackPosition`.
 */

import { hasAccessibleName } from "../../a11y/accessible-name";
import { hideOthers } from "../../a11y/aria-hidden";
import { lockScroll } from "../../a11y/scroll-lock";
import { observeChildren } from "../../dom/observers";
import { contains, query } from "../../dom/query";
import { resolveDir } from "../../dom/text-dir";
import {
  resolveEnvironment,
  trackEnvironment as watchEnvironment,
} from "../../environment/environment";
import { trapFocus } from "../../focus/focus-trap";
import { proxyTabFocus } from "../../focus/proxy-tab-focus";
import { restoreFocus } from "../../focus/restore-focus";
import { trackDismissableLayer } from "../../interaction/dismissable";
import { getLayerStack, isEscapeLikeDismissal } from "../../interaction/layer-stack";
import { createMachine } from "../../machine/create-machine";
import type { Machine } from "../../machine/types";
import { focusElement, getFirstTabbable, trackInputModality } from "../../nav";
import { trackPosition } from "../../positioner/track-position";
import type { Density, Direction } from "../../types";
import { isDev } from "../../utils/env";
import { warn } from "../../utils/invariant";
import {
  getAnchorEl,
  getArrowEl,
  getBackdropEl,
  getContentEl,
  getContentId,
  getDirAnchorEl,
  getEnvironmentEl,
  getPositionerEl,
  getTriggerEl,
  hasPart,
} from "./popover.dom";
import type { PopoverSchema } from "./popover.types";

/** The inline properties `trackPosition` writes and never cleans up itself. */
const POSITION_STYLES = ["position", "top", "left", "transform", "width"] as const;

export const machine: Machine<PopoverSchema> = createMachine<PopoverSchema>({
  props({ props }) {
    const modal = props.modal ?? false;
    return {
      defaultOpen: false,
      presentation: "auto",
      placement: "bottom",
      // Air only. The arrow's depth is added on top by the effect, which measures
      // the rendered node — `arrowSize` clamps the cross axis and offsets nothing.
      gap: 8,
      offset: 0,
      flip: true,
      shift: true,
      padding: 8,
      // Measured to the arrow's **box** edge, the convention `computePosition`
      // clamps in. Derived as a ratio rather than copied as a
      // literal: the margin does not scale with the radius.
      arrowPadding: 20,
      matchWidth: false,
      strategy: "fixed",
      autoFocus: true,
      restoreFocus: true,
      closeOnEscape: true,
      closeOnInteractOutside: true,
      disabled: false,
      intents: null,
      ...props,
      modal,
      // The same words as the dialog: a surface that leaves the page reachable on
      // purpose must not hold Tab inside itself.
      trapFocus: modal && (props.trapFocus ?? true),
      preventScroll: props.preventScroll ?? modal,
      // A popover hung off a text field wants to survive the caret moving on, and
      // a non-modal surface is exactly the one a focus can walk out of.
      closeOnFocusOutside: props.closeOnFocusOutside ?? !modal,
    };
  },

  context({ prop, bindable }) {
    return {
      open: bindable<boolean>(() => ({
        defaultValue: prop("defaultOpen"),
        value: prop("open"),
        onChange: (open) => prop("onOpenChange")?.({ open }),
        debugLabel: "popover open",
      })),
      density: bindable<Density>(() => ({ defaultValue: "desktop" })),
      surfaceDir: bindable<Direction | null>(() => ({ defaultValue: null })),
      // Seeded from the prop rather than from a constant: the server renders
      // `data-side` from this, and the first paint has to agree with the markup.
      currentPlacement: bindable(() => ({ defaultValue: prop("placement") })),
      hasTitle: bindable<boolean>(() => ({ defaultValue: false })),
      hasDescription: bindable<boolean>(() => ({ defaultValue: false })),
    };
  },

  computed: {
    presentation({ prop, context }) {
      const requested = prop("presentation");
      if (requested !== "auto") return requested;
      // A coarse pointer gets the sheet, which is the iPhone behaviour. An iPad is
      // `touch` too and is the one platform where the anchored popover exists —
      // so an iPad app declares `presentation="anchored"`. The library cannot
      // infer the device.
      return context.get("density") === "touch" ? "sheet" : "anchored";
    },
  },

  refs() {
    return { finalFocusEl: null };
  },

  initialState({ prop }) {
    return (prop("open") ?? prop("defaultOpen")) ? "open" : "closed";
  },

  effects: ["trackEnvironment", "trackModality"],

  watch({ context, computed, scope, track, send, action }) {
    track(
      () => [context.get("open")],
      () => send({ type: "OPEN.SYNC" }),
    );
    track(
      () => [computed("presentation")],
      () => send({ type: "PRESENTATION.SYNC" }),
    );
    // No `arrow` here, and none in the context either: the position effect measures
    // the rendered node itself, one source of truth, and it runs before `trackParts`
    // could have told it anything. A `hasArrow` flag would be state nobody reads.
    track(
      () => [hasPart(scope, "title"), hasPart(scope, "description")],
      () => action(["syncParts"]),
    );
  },

  on: {
    // A disclosure, not the dialog's open-only trigger: the same button closes it.
    "TRIGGER.CLICK": { guard: "isEnabled", actions: ["togglePopover"] },
    "TRIGGER.KEYDOWN": { guard: "shouldEnterOnTab", actions: ["focusFirstInside"] },
    "CLOSE.CLICK": { actions: ["closePopover"] },
    "CONTENT.DISMISS": { guard: "canDismiss", actions: ["invokeOnDismiss", "closePopover"] },
    "CONTENT.FOCUS": { actions: ["focusInitial"] },
    "POSITION.SYNC": { actions: ["syncPlacement"] },
    "OPEN.SET": { actions: ["setOpen"] },
    "OPEN.SYNC": [{ guard: "isOpen", target: "open" }, { target: "closed" }],
    "PRESENTATION.SYNC": { guard: "isOpen", target: "open", reenter: true },
    "ENVIRONMENT.SYNC": { actions: ["syncEnvironment"] },
    "PARTS.SYNC": { actions: ["syncParts"] },
  },

  states: {
    // Exit rather than the open state's entry, for the dialog's exact reason: the
    // interpreter installs effects before entry actions, and `hideOutside` makes
    // the trigger's ancestor `inert`, which blurs it.
    closed: { exit: ["captureFinalFocus"] },
    open: {
      entry: ["focusInitialIfAuto"],
      effects: [
        "trackSurfaceDir",
        "trackDismissable",
        "lockPageScroll",
        "trackAnchorPosition",
        "trapPopoverFocus",
        "proxyTabs",
        "hideOutside",
        "captureIntents",
        "trackParts",
      ],
    },
  },

  implementations: {
    guards: {
      isEnabled: ({ prop }) => !prop("disabled"),
      isOpen: ({ context }) => context.get("open"),

      /** Read live from the props, never snapshotted into the layer at install. */
      canDismiss({ prop, event }) {
        if (event.type !== "CONTENT.DISMISS") return false;
        if (isEscapeLikeDismissal(event.reason)) return prop("closeOnEscape");
        if (event.reason === "focus-outside") return prop("closeOnFocusOutside");
        return prop("closeOnInteractOutside");
      },

      /**
       * `proxy-tab-focus` handles leaving the surface, never entering it. With
       * `autoFocus: false` the surface opens and the focus stays on the trigger,
       * so Tab has to be what walks in — otherwise the next Tab jumps straight
       * past a surface the user just opened.
       */
      shouldEnterOnTab({ prop, context, event }) {
        if (event.type !== "TRIGGER.KEYDOWN") return false;
        return context.get("open") && !prop("autoFocus") && event.key === "Tab" && !event.shiftKey;
      },
    },

    actions: {
      togglePopover({ context }) {
        context.set("open", !context.get("open"));
      },

      closePopover({ context }) {
        context.set("open", false);
      },

      setOpen({ context, event }) {
        if (event.type === "OPEN.SET") context.set("open", event.open);
      },

      invokeOnDismiss({ prop, event }) {
        if (event.type === "CONTENT.DISMISS") prop("onDismiss")?.({ reason: event.reason });
      },

      captureFinalFocus({ refs, scope }) {
        const active = scope.getActiveElement();
        refs.set("finalFocusEl", active === null || active.tagName === "BODY" ? null : active);
      },

      syncEnvironment({ context, event }) {
        if (event.type === "ENVIRONMENT.SYNC") context.set("density", event.density);
      },

      syncPlacement({ context, event }) {
        if (event.type === "POSITION.SYNC") context.set("currentPlacement", event.placement);
      },

      syncParts({ context, scope }) {
        context.set("hasTitle", hasPart(scope, "title"));
        context.set("hasDescription", hasPart(scope, "description"));
      },

      focusInitial({ prop, scope }) {
        const content = getContentEl(scope);
        if (content === null) return;
        focusElement(prop("initialFocus")?.() ?? getFirstTabbable(content) ?? content);
      },

      /**
       * Skipped when a trap is installed, because the trap does the same job with
       * the same fallbacks — running both would focus twice and fire two
       * `focusin` events at whatever is listening.
       */
      focusInitialIfAuto({ prop, scope }) {
        if (!prop("autoFocus") || prop("trapFocus")) return;
        const content = getContentEl(scope);
        if (content === null) return;
        focusElement(prop("initialFocus")?.() ?? getFirstTabbable(content) ?? content);
      },

      focusFirstInside({ scope }) {
        const content = getContentEl(scope);
        if (content === null) return;
        focusElement(getFirstTabbable(content) ?? content);
      },
    },

    effects: {
      trackEnvironment({ scope, send }) {
        const node = getEnvironmentEl(scope);
        const onChange = (density: Density): void => send({ type: "ENVIRONMENT.SYNC", density });
        onChange(resolveEnvironment(node).density);
        return watchEnvironment(node, {
          onChange: (environment) => onChange(environment.density),
        });
      },

      trackModality({ scope }) {
        if (scope.getRootNode() === null) return;
        return trackInputModality(scope.getDoc());
      },

      trackDismissable({ scope, prop, send }) {
        return trackDismissableLayer(getContentEl(scope), {
          id: getContentId(scope),
          type: "popover",
          modal: prop("modal"),
          parentId: prop("parentId"),
          // The anchor joins the trigger here: a popover anchored to a toolbar
          // must not dismiss when the user clicks the toolbar it points at.
          exclude: () => [
            getTriggerEl(scope),
            getAnchorEl(scope),
            ...(prop("persistentElements")?.() ?? []),
          ],
          // A literal, and the gate is `canDismiss`, which reads the prop live.
          // The focus channel is a separate lock here — that is the whole point
          // of the popover having `closeOnFocusOutside` at all.
          dismissOnFocusOutside: true,
          onDismiss: (reason) => send({ type: "CONTENT.DISMISS", reason }),
        });
      },

      lockPageScroll({ prop, scope }) {
        if (!prop("modal") || !prop("preventScroll")) return;
        return lockScroll(getContentEl(scope)?.ownerDocument);
      },

      /**
       * Third, before anything that moves the focus: focus landing in a surface
       * still parked at `0,0` makes the browser scroll the page there to reveal
       * it, and the surface then jumps into place under a scrolled viewport.
       *
       * The sheet branch clears the inline styles a previous anchored pass left
       * behind, and it does it **on install rather than on teardown**.
       * `trackPosition` does not clean up after itself, and cleaning up in the
       * disposer would run while `open` is going false with the node still
       * mounted by `presence` — the surface would snap to `0,0` in the middle of
       * its exit animation. Clearing on the way in has neither problem.
       */
      /**
       * The surface is the one part that emits a `dir` nobody asked for,
       * and the portal is the whole reason. The adapter mounts it into
       * `document.body` (react/src/portal.tsx), outside whatever RTL region the
       * trigger sits in, and inheritance does not cross a portal — so the
       * direction has to be carried over explicitly. What was removed everywhere is the
       * ltr DEFAULT, not the attribute: a part still emits `dir` when the consumer
       * passes one. The default was the bug — emitting a direction nobody asked
       * for *overrode* the inheritance that already worked.
       *
       * Read from the anchor, never from the surface: the surface is in the body
       * and would only report the document's own direction back to itself. And in
       * an effect rather than in `connect`, so the server emits nothing and the
       * first client render has nothing to disagree with.
       */
      trackSurfaceDir({ prop, context, scope }) {
        context.set("surfaceDir", resolveDir(prop("dir"), getDirAnchorEl(scope)));
      },

      trackAnchorPosition({ prop, computed, scope, send }) {
        const positioner = getPositionerEl(scope);
        if (positioner === null) return;

        if (computed("presentation") !== "anchored") {
          for (const name of POSITION_STYLES) positioner.style.removeProperty(name);
          positioner.style.removeProperty("--sui-transform-origin");
          return;
        }

        // One source of truth for the arrow's size, and it is the stylesheet: the
        // token draws it, the effect measures what was drawn. `offsetWidth` is the
        // length along the cross axis and `offsetHeight` the depth into the gap —
        // the CSS box is the same either way, the rotation is a transform and
        // transforms do not move layout boxes.
        const arrow = getArrowEl(scope);
        const arrowSize = arrow?.offsetWidth ?? 0;
        const arrowDepth = arrow?.offsetHeight ?? 0;

        return trackPosition(getAnchorEl(scope), positioner, {
          placement: prop("placement"),
          gap: prop("gap") + arrowDepth,
          offset: prop("offset"),
          flip: prop("flip"),
          shift: prop("shift"),
          padding: prop("padding"),
          arrowSize,
          arrowPadding: prop("arrowPadding"),
          matchWidth: prop("matchWidth"),
          // From the anchor, not from the surface: the surface is portalled into
          // `document.body` and would report the document's direction, while
          // `start`/`end` alignment belongs to the region the anchor sits in.
          dir: resolveDir(prop("dir"), getDirAnchorEl(scope)),
          strategy: prop("strategy"),
          boundary: prop("boundary"),
          getAnchorRect: prop("getAnchorRect"),
          arrowNode: () => getArrowEl(scope),
          onPositioned: (result) => send({ type: "POSITION.SYNC", placement: result.placement }),
        });
      },

      trapPopoverFocus({ prop, refs, scope }) {
        if (!prop("trapFocus")) return;
        const content = getContentEl(scope);
        const id = getContentId(scope);
        return trapFocus(content, {
          initialFocus: () => prop("initialFocus")?.() ?? null,
          finalFocus: () => prop("finalFocus")?.() ?? refs.get("finalFocusEl"),
          restoreFocus: prop("restoreFocus"),
          loop: true,
          owns: (target) =>
            content !== null && getLayerStack(content.ownerDocument).containsTarget(id, target),
        });
      },

      /**
       * The default path for a popover, and the module was written for it. A
       * popover opened from a store has no trigger, only an anchor, and Tab out
       * of it belongs after that anchor rather than at the end of the document. A
       * trigger disabled while open takes nothing, so `restoreFocus` falls back on
       * its neighbour (R61).
       */
      proxyTabs({ prop, refs, scope }) {
        if (prop("trapFocus")) return;
        const dispose = proxyTabFocus(getContentEl(scope), {
          triggerNode: () => getTriggerEl(scope) ?? getAnchorEl(scope),
        });
        if (!prop("restoreFocus")) return dispose;
        return () => {
          const content = getContentEl(scope);
          const inside = contains(content, scope.getActiveElement());
          dispose();
          if (!inside) return;
          const target = prop("finalFocus")?.() ?? refs.get("finalFocusEl");
          restoreFocus(target, content);
        };
      },

      /**
       * The arrow is listed even though it is the positioner's own child, for the
       * same reason the dialog lists the content: the kept list is read as the
       * statement of what stays reachable, and a reader should not have to
       * reconstruct the tree to be sure the tip did not go inert with the page.
       */
      hideOutside({ prop, scope }) {
        if (!prop("modal")) return;
        return hideOthers(
          [
            getContentEl(scope),
            getPositionerEl(scope),
            getArrowEl(scope),
            getBackdropEl(scope),
            ...(prop("persistentElements")?.() ?? []),
          ],
          { inert: true },
        );
      },

      /**
       * **Not `trapped`, and that is a deliberate divergence from the dialog.** A
       * trapped scope answers `consumed` for everything it declines, and the
       * spatial engine sits at the bottom of the stack — so a trapped surface
       * makes its own interior unreachable to a d-pad. Confinement is declared
       * where it belongs instead: `data-snav-trap` on the content, plus the
       * `inert` page when modal.
       */
      captureIntents({ prop, scope, send }) {
        const host = prop("intents");
        const content = getContentEl(scope);
        if (host === null || host === undefined || content === null) return;
        const id = getContentId(scope);
        const stack = getLayerStack(content.ownerDocument);
        return host.pushScope((event) => {
          if (event.intent !== "back") return false;
          if (!prop("closeOnEscape") || !stack.isTopMost(id)) return false;
          send({ type: "CONTENT.DISMISS", reason: "back" });
          return true;
        });
      },

      /** Watches the **positioner**: the arrow is not inside the content. */
      trackParts({ scope, send }) {
        send({ type: "PARTS.SYNC" });
        const positioner = getPositionerEl(scope);
        const close = query(positioner, '[data-part~="popover:close-trigger"]');
        warn(
          isDev() && close !== null && !hasAccessibleName(close),
          "a popover close trigger has no accessible name — give it text, `aria-label` or `title`",
        );
        return observeChildren(positioner, () => send({ type: "PARTS.SYNC" }));
      },
    },
  },
});

import type { DismissReason } from "../../interaction/layer-stack";
import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { IntentScopeHost } from "../../nav";
import type { Placement } from "../../positioner/compute-position";
import type { Density, Direction, Rect } from "../../types";

/** What the surface actually is once the density has had its say. */
export type PopoverPresentation = "anchored" | "sheet";

export type PopoverPresentationProp = "auto" | PopoverPresentation;

export interface PopoverOpenChangeDetails {
  readonly open: boolean;
}

export interface PopoverDismissDetails {
  readonly reason: DismissReason;
}

export interface PopoverMachineProps {
  readonly open?: boolean | undefined;
  readonly defaultOpen?: boolean | undefined;
  /**
   * `false`, which is the inverse of the dialog and is the definition of a
   * popover: the page behind it stays live, readable and clickable.
   */
  readonly modal?: boolean | undefined;
  readonly presentation?: PopoverPresentationProp | undefined;

  // --- positioning, handed straight to the positioner ------------------------
  readonly placement?: Placement | undefined;
  /**
   * Air between the anchor and the surface. The arrow's depth is **added to this
   * by the effect**, which measures the rendered node: `arrowSize` only ever
   * clamps the cross axis, it never offsets the surface, so a popover that
   * forgot the addition would drive its own tip into the anchor.
   */
  readonly gap?: number | undefined;
  readonly offset?: number | undefined;
  readonly flip?: boolean | undefined;
  readonly shift?: boolean | undefined;
  readonly padding?: number | undefined;
  /** How far the arrow is kept from a corner, measured to its **box** edge. */
  readonly arrowPadding?: number | undefined;
  readonly matchWidth?: boolean | undefined;
  readonly strategy?: "absolute" | "fixed" | undefined;
  readonly boundary?: (() => Rect) | undefined;
  /** Anchor to a rect instead of an element — a caret, a range, a point. */
  readonly getAnchorRect?: (() => Rect) | undefined;

  // --- focus, dismissal, the rest identical to `DialogMachineProps` -----------------
  readonly autoFocus?: boolean | undefined;
  /** Forced off when the popover is not modal — there is nothing to trap against. */
  readonly trapFocus?: boolean | undefined;
  readonly restoreFocus?: boolean | undefined;
  /** Ignored when the popover is not modal. */
  readonly preventScroll?: boolean | undefined;
  /** Governs the gamepad `back` intent as well: B and Escape share one lock. */
  readonly closeOnEscape?: boolean | undefined;
  readonly closeOnInteractOutside?: boolean | undefined;
  /**
   * Separate from the pointer lock, and only expressible since `interact-outside`
   * stopped reporting a focus departure as a pointer one. A popover hung off a
   * text field wants "close on a click outside" without "close when the caret
   * moves on", and that combination is this pair of booleans.
   */
  readonly closeOnFocusOutside?: boolean | undefined;
  /** Disables the trigger, not the popover. */
  readonly disabled?: boolean | undefined;
  /** Not defaulted, deliberately: left unset the resolved page direction governs, so a subtree inside an RTL region inherits instead of being reset to `ltr`. */
  readonly dir?: Direction | undefined;
  readonly initialFocus?: (() => HTMLElement | null) | undefined;
  readonly finalFocus?: (() => HTMLElement | null) | undefined;
  readonly persistentElements?: (() => readonly HTMLElement[]) | undefined;
  readonly parentId?: string | undefined;
  readonly describedBy?: string | undefined;
  /** The accessible name used when no `title` part is rendered. */
  readonly label?: string | undefined;
  readonly intents?: IntentScopeHost | null | undefined;
  readonly onOpenChange?: ((details: PopoverOpenChangeDetails) => void) | undefined;
  readonly onDismiss?: ((details: PopoverDismissDetails) => void) | undefined;
}

export interface ResolvedPopoverMachineProps extends PopoverMachineProps {
  readonly defaultOpen: boolean;
  readonly modal: boolean;
  readonly presentation: PopoverPresentationProp;
  readonly placement: Placement;
  readonly gap: number;
  readonly offset: number;
  readonly flip: boolean;
  readonly shift: boolean;
  readonly padding: number;
  readonly arrowPadding: number;
  readonly matchWidth: boolean;
  readonly strategy: "absolute" | "fixed";
  readonly autoFocus: boolean;
  readonly trapFocus: boolean;
  readonly restoreFocus: boolean;
  readonly preventScroll: boolean;
  readonly closeOnEscape: boolean;
  readonly closeOnInteractOutside: boolean;
  readonly closeOnFocusOutside: boolean;
  readonly disabled: boolean;
  readonly intents: IntentScopeHost | null;
}

export interface PopoverSchema extends MachineSchema {
  state: "open" | "closed";
  props: ResolvedPopoverMachineProps;
  context: {
    /** The single source of truth; the state is a projection of it. */
    open: boolean;
    density: Density;
    /**
     * The direction the portalled surface is drawn in, resolved from the anchor
     * when it opens. `null` until then — and on the server — which is what keeps
     * the first client render agreeing with the markup it hydrates.
     */
    surfaceDir: Direction | null;
    /** Where the surface actually landed — the preferred placement may have flipped. */
    currentPlacement: Placement;
    hasTitle: boolean;
    hasDescription: boolean;
  };
  computed: { presentation: PopoverPresentation };
  refs: { finalFocusEl: HTMLElement | null };
  event:
    | { type: "TRIGGER.CLICK" }
    | { type: "TRIGGER.KEYDOWN"; key: string; shiftKey: boolean }
    | { type: "CLOSE.CLICK" }
    | { type: "CONTENT.DISMISS"; reason: DismissReason }
    | { type: "CONTENT.FOCUS" }
    | { type: "POSITION.SYNC"; placement: Placement }
    | { type: "PRESENTATION.SYNC" }
    | { type: "OPEN.SET"; open: boolean }
    | { type: "OPEN.SYNC" }
    | { type: "ENVIRONMENT.SYNC"; density: Density }
    | { type: "PARTS.SYNC" };
  action:
    | "togglePopover"
    | "closePopover"
    | "setOpen"
    | "invokeOnDismiss"
    | "captureFinalFocus"
    | "syncEnvironment"
    | "syncParts"
    | "syncPlacement"
    | "focusInitial"
    | "focusInitialIfAuto"
    | "focusFirstInside";
  guard: "isEnabled" | "isOpen" | "canDismiss" | "shouldEnterOnTab";
  effect:
    | "trackEnvironment"
    | "trackModality"
    | "trackSurfaceDir"
    | "trackDismissable"
    | "lockPageScroll"
    | "trackAnchorPosition"
    | "trapPopoverFocus"
    | "proxyTabs"
    | "hideOutside"
    | "captureIntents"
    | "trackParts";
}

export interface PopoverApi<T extends PropTypes = PropTypes> {
  readonly open: boolean;
  readonly modal: boolean;
  readonly presentation: PopoverPresentation;
  /** Where the surface landed, which is not necessarily what was asked for. */
  readonly placement: Placement;
  setOpen(open: boolean): void;
  focusInitial(): void;
  getTriggerProps(): T["button"];
  getAnchorProps(): T["element"];
  getBackdropProps(): T["element"];
  getPositionerProps(): T["element"];
  getContentProps(): T["element"];
  getArrowProps(): T["element"];
  getArrowTipProps(): T["element"];
  getTitleProps(): T["element"];
  getDescriptionProps(): T["element"];
  getCloseTriggerProps(): T["button"];
}

/**
 * The popover in React: the dialog's shape, plus an anchor, an arrow, and the one
 * thing the dialog never had to decide — what to render when the density says the
 * surface should be a sheet instead.
 *
 * Like the dialog, the root renders no element: the trigger stays where the author
 * wrote it and the surface is portalled, so the two are siblings. The intent scope
 * and the parent layer id are wired here for the same reasons, and the parenthood
 * travels on the shared `layer-context` rather than on a private one — what opens
 * inside a dialog is as often a popover as another dialog.
 */

import type { Service } from "@standarui/core";
import * as popover from "@standarui/core/popover";
import { type ReactNode, type Ref, useMemo } from "react";
import { composeRefs } from "../../compose-refs";
import { createPart, type PartProps } from "../../create-part";
import { useEnvironment } from "../../environment";
import { LayerProvider, useParentLayerId } from "../../layer-context";
import { useIntentScopeHost } from "../../nav";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { Portal, type PortalProps } from "../../portal";
import { type PresenceApi, usePresence } from "../../presence";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type PopoverApi = popover.PopoverApi<ReactPropTypes>;

export interface UsePopoverProps extends popover.PopoverMachineProps, MachineRuntimeProps {}

interface PopoverContextValue {
  readonly api: PopoverApi;
  readonly keepMounted: boolean;
  readonly backdrop: PresenceApi;
  readonly content: PresenceApi;
}

const PopoverContext = createPartContext<PopoverContextValue>("Popover");

function usePopoverService(props: UsePopoverProps): Service<popover.PopoverSchema> {
  const parentLayerId = useParentLayerId();
  const host = useIntentScopeHost();

  return useMachine(popover.machine, {
    ...props,
    // `??` would override an explicit `null`, which is how a consumer says "this
    // surface answers no gamepad" while a provider is mounted above it.
    intents: props.intents === undefined ? host : props.intents,
    parentId: props.parentId ?? parentLayerId,
  });
}

export function usePopover(props: UsePopoverProps): PopoverApi {
  return popover.connect(usePopoverService(props), normalizeProps);
}

export function usePopoverContext(): PopoverApi {
  return PopoverContext.usePart("PopoverContext").api;
}

export interface PopoverRootProps extends UsePopoverProps {
  readonly keepMounted?: boolean | undefined;
  readonly children?: ReactNode;
}

export function PopoverRoot(props: PopoverRootProps): ReactNode {
  const { children, keepMounted, ...machineProps } = props;
  const service = usePopoverService(machineProps);
  const api = popover.connect(service, normalizeProps);
  const { motion } = useEnvironment();
  // See the note in `dialog.tsx`: `reduced` keeps the fade, only `none` removes it.
  const immediate = motion === "none";

  // Two presences: the scrim and the surface run different exits, and one
  // presence can only measure the animations of the node it holds.
  const backdrop = usePresence({ present: api.open, immediate });
  const content = usePresence({ present: api.open, immediate });

  const value: PopoverContextValue = {
    api,
    keepMounted: keepMounted === true,
    backdrop,
    content,
  };

  return (
    <LayerProvider layerId={popover.getContentId(service.scope)}>
      <PopoverContext.Provider value={value}>{children}</PopoverContext.Provider>
    </LayerProvider>
  );
}

/**
 * Read straight off the machine in the open direction, never off the presence:
 * the interpreter installs the open state's effects in the layout effect of the
 * very commit that opened it, and every one of them looks the surface up by id.
 * The presence only ever extends the mount past the close.
 */
function isMounted(context: PopoverContextValue, presence: PresenceApi): boolean {
  return context.keepMounted || context.api.open || presence.present;
}

function usePresenceRef(
  presence: PresenceApi,
  consumer: Ref<HTMLElement> | undefined,
): Ref<HTMLElement> {
  return useMemo(() => composeRefs(presence.ref, consumer), [presence.ref, consumer]);
}

export const PopoverTrigger: (props: PartProps<"button">) => ReactNode = createPart(
  PopoverContext,
  {
    name: "PopoverTrigger",
    element: "button",
    props: (context) => context.api.getTriggerProps(),
  },
);

/** Only for a surface that points at something other than what opened it. */
export const PopoverAnchor: (props: PartProps<"div">) => ReactNode = createPart(PopoverContext, {
  name: "PopoverAnchor",
  element: "div",
  props: (context) => context.api.getAnchorProps(),
});

export interface PopoverPortalProps extends Omit<PortalProps, "children"> {
  readonly children?: ReactNode;
}

export function PopoverPortal(props: PopoverPortalProps): ReactNode {
  const { children, ...portalProps } = props;
  const context = PopoverContext.usePart("PopoverPortal");
  const present = isMounted(context, context.backdrop) || isMounted(context, context.content);
  return present ? <Portal {...portalProps}>{children}</Portal> : null;
}

/**
 * Rendered in both presentations and hidden by the sheet in one of them, rather
 * than mounted conditionally: the scrim is a paint decision, and a consumer who
 * wants a dimmed anchored popover should get it by writing CSS, not by learning
 * which presentation is allowed to have one.
 *
 * Spelled out here and again in the content below, rather than folded into one
 * factory. That was tried and measured: the factory took the minified bundle from
 * 3.15 to 3.02 kB and the **gzipped** one from 1.05 to 1.10 — two near-identical
 * component bodies compress almost to nothing, and replacing them with unique
 * code costs more than the text it removes. Same lesson as splitting a budget
 * line in two; the number that governs is the one after compression.
 */
export function PopoverBackdrop(props: PartProps<"div">): ReactNode {
  const { render, asChild, children, ref, ...elementProps } = props;
  const context = PopoverContext.usePart("PopoverBackdrop");
  const composed = usePresenceRef(context.backdrop, ref);

  const element = useRender({
    render,
    asChild,
    element: "div",
    props: context.api.getBackdropProps(),
    elementProps: { ...elementProps, ref: composed },
    children,
  });

  return isMounted(context, context.backdrop) ? element : null;
}

export function PopoverPositioner(props: PartProps<"div">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;
  const context = PopoverContext.usePart("PopoverPositioner");

  const element = useRender({
    render,
    asChild,
    element: "div",
    props: context.api.getPositionerProps(),
    elementProps,
    children,
  });

  return isMounted(context, context.content) ? element : null;
}

export function PopoverContent(props: PartProps<"div">): ReactNode {
  const { render, asChild, children, ref, ...elementProps } = props;
  const context = PopoverContext.usePart("PopoverContent");
  const composed = usePresenceRef(context.content, ref);

  const element = useRender({
    render,
    asChild,
    element: "div",
    props: context.api.getContentProps(),
    elementProps: { ...elementProps, ref: composed },
    children,
  });

  return isMounted(context, context.content) ? element : null;
}

/**
 * A **sibling of the content**, inside the positioner — never a child of the
 * surface: `contain: layout paint` on a glass surface would clip it away, and the
 * effect writes `--sui-arrow-x/y` relative to the floating element's origin.
 *
 * Unmounted in the sheet presentation, where there is no anchor to point at.
 *
 * The tip is drawn here rather than exported as a part component of its own. It
 * is still a part in the anatomy — `arrow` is what the effect writes on and
 * `arrow-tip` is what the sheet clips, and keeping them apart is what lets a
 * `clip-path` live on a node nothing is translating. But there is nothing a
 * consumer would ever put inside it, and an arrow whose silhouette the author
 * forgot to compose draws nothing at all, which reads as a styling bug rather
 * than as a missing element.
 */
export function PopoverArrow(props: PartProps<"div">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;
  const context = PopoverContext.usePart("PopoverArrow");

  // Rendered then discarded rather than returned early: `useRender` is a hook,
  // and a presentation flip must not change how many of them this component runs.
  const element = useRender({
    render,
    asChild,
    element: "div",
    props: context.api.getArrowProps(),
    elementProps,
    children: children ?? <div {...context.api.getArrowTipProps()} />,
  });

  return context.api.presentation === "sheet" ? null : element;
}

export const PopoverTitle: (props: PartProps<"h2">) => ReactNode = createPart(PopoverContext, {
  name: "PopoverTitle",
  element: "h2",
  props: (context) => context.api.getTitleProps(),
});

export const PopoverDescription: (props: PartProps<"p">) => ReactNode = createPart(PopoverContext, {
  name: "PopoverDescription",
  element: "p",
  props: (context) => context.api.getDescriptionProps(),
});

export const PopoverCloseTrigger: (props: PartProps<"button">) => ReactNode = createPart(
  PopoverContext,
  {
    name: "PopoverCloseTrigger",
    element: "button",
    props: (context) => context.api.getCloseTriggerProps(),
  },
);
